PRAGMA user_version = 1;
PRAGMA foreign_keys = ON;
CREATE TABLE meta(key TEXT PRIMARY KEY, value TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE sources(source_id TEXT PRIMARY KEY, language TEXT NOT NULL, name TEXT NOT NULL, kind TEXT NOT NULL, locator TEXT NOT NULL, sha256 TEXT NOT NULL, attribution TEXT NOT NULL, metadata TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE books(book_id TEXT PRIMARY KEY, abbr TEXT UNIQUE NOT NULL, name_en TEXT NOT NULL, name_pl TEXT NOT NULL, position INTEGER UNIQUE NOT NULL) WITHOUT ROWID;
CREATE TABLE source_books(source_id TEXT REFERENCES sources,book_id TEXT REFERENCES books,PRIMARY KEY(source_id,book_id)) WITHOUT ROWID;
CREATE TABLE verses(source_id TEXT, book_id TEXT, chapter INTEGER NOT NULL CHECK(chapter>0), verse INTEGER NOT NULL CHECK(verse>0), text TEXT NOT NULL, PRIMARY KEY(source_id,book_id,chapter,verse), FOREIGN KEY(source_id,book_id) REFERENCES source_books);
CREATE INDEX comparison ON verses(book_id,chapter,verse,source_id);
CREATE TABLE search_documents(doc_id INTEGER PRIMARY KEY, kind TEXT NOT NULL,source TEXT NOT NULL,target TEXT NOT NULL,chapter INTEGER NOT NULL,verse INTEGER NOT NULL,text TEXT NOT NULL,normalized TEXT NOT NULL);
CREATE VIRTUAL TABLE corpus_fts USING fts5(normalized, content='search_documents',content_rowid='doc_id',tokenize='unicode61');
CREATE TABLE verse_footnotes(source_id TEXT,book_id TEXT,chapter INTEGER,verse INTEGER,note_ordinal INTEGER, label TEXT NOT NULL,body TEXT NOT NULL,raw_body TEXT NOT NULL, start_offset INTEGER NOT NULL,end_offset INTEGER NOT NULL, PRIMARY KEY(source_id,book_id,chapter,verse,note_ordinal), FOREIGN KEY(source_id,book_id,chapter,verse) REFERENCES verses(source_id,book_id,chapter,verse)) WITHOUT ROWID;
CREATE TABLE verse_runs(source_id TEXT,book_id TEXT,chapter INTEGER,verse INTEGER,ordinal INTEGER,kind TEXT NOT NULL,text TEXT NOT NULL,styles TEXT NOT NULL,note_ordinal INTEGER,raw_text TEXT NOT NULL,locator TEXT NOT NULL, PRIMARY KEY(source_id,book_id,chapter,verse,ordinal), FOREIGN KEY(source_id,book_id,chapter,verse) REFERENCES verses(source_id,book_id,chapter,verse), FOREIGN KEY(source_id,book_id,chapter,verse,note_ordinal) REFERENCES verse_footnotes) WITHOUT ROWID;
CREATE TABLE fathers_works(work_id TEXT PRIMARY KEY,name_en TEXT NOT NULL,position INTEGER NOT NULL) WITHOUT ROWID;
CREATE TABLE fathers_passages(work_id TEXT REFERENCES fathers_works,chapter INTEGER CHECK(chapter>=0),ordinal INTEGER CHECK(ordinal>=1),text TEXT NOT NULL,PRIMARY KEY(work_id,chapter,ordinal)) WITHOUT ROWID;
CREATE TABLE tags(slug TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL,markdown TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE tag_ranges(slug TEXT REFERENCES tags,ordinal INTEGER,fragment TEXT NOT NULL,PRIMARY KEY(slug,ordinal)) WITHOUT ROWID;
CREATE TABLE tag_verses(slug TEXT REFERENCES tags,book_id TEXT REFERENCES books,chapter INTEGER,verse INTEGER,PRIMARY KEY(slug,book_id,chapter,verse)) WITHOUT ROWID;
CREATE TABLE tag_fathers(slug TEXT REFERENCES tags,work_id TEXT,chapter INTEGER,ordinal INTEGER,PRIMARY KEY(slug,work_id,chapter,ordinal), FOREIGN KEY(work_id,chapter,ordinal) REFERENCES fathers_passages) WITHOUT ROWID;
CREATE TABLE interlinear_tokens(book_id TEXT REFERENCES books,chapter INTEGER,verse INTEGER,position INTEGER,greek TEXT NOT NULL,polish TEXT NOT NULL,english TEXT NOT NULL,grammar TEXT NOT NULL,code TEXT NOT NULL,pronunciation TEXT NOT NULL,form_key TEXT NOT NULL, PRIMARY KEY(book_id,chapter,verse,position)) WITHOUT ROWID;
CREATE TABLE strong_tokens(book_id TEXT REFERENCES books,chapter INTEGER,verse INTEGER,position INTEGER,greek TEXT NOT NULL,form_key TEXT NOT NULL,strong INTEGER,grammar TEXT,definition TEXT,lemma TEXT,transliteration TEXT,grammar_human TEXT,raw_record TEXT NOT NULL,PRIMARY KEY(book_id,chapter,verse,position)) WITHOUT ROWID;
CREATE INDEX strong_grammar ON strong_tokens(strong,grammar,form_key);
CREATE TABLE form_senses(form_key TEXT NOT NULL,form TEXT NOT NULL,source TEXT NOT NULL,polish TEXT,english TEXT,grammar TEXT,code TEXT,pronunciation TEXT,lemma TEXT,raw_record TEXT NOT NULL);
CREATE INDEX sense_lookup ON form_senses(form_key);
